-- Expect: 212 invoices, 1599.19 t, 46,538,464.5 cash + 6,762,575 credit, 12 settled payments totalling 6,762,575.
select count(*)                      as invoices,
       round(sum(qty), 3)            as tonnes,
       round(sum(invoice_cash), 2)   as cash_etb,
       round(sum(invoice_credit), 2) as credit_etb,
       (select round(coalesce(sum(p.amount), 0), 2)
          from sales_credit_payments p
          join sales_invoices i on i.id = p.invoice_id
         where i.date >= '2026-07-01T00:00:00.000Z' and i.date < '2026-08-01T00:00:00.000Z'
           and i.reported_by = 'historical import') as credit_collected_etb
  from sales_invoices
 where date >= '2026-07-01T00:00:00.000Z' and date < '2026-08-01T00:00:00.000Z'
   and reported_by = 'historical import';
